  <p class="sa-hint">\u4EE5\u4E0A\u6309\u94AE\u7ACB\u5373\u64CD\u4F5C\u5F53\u524D\u697C\u5C42\uFF0C\u5E76\u6682\u505C\u672C\u804A\u5929\u7684\u81EA\u52A8\u9690\u85CF\u3002\u91CD\u65B0\u5F00\u542F\u4F1A\u6E05\u9664\u8FD9\u91CC\u7684\u624B\u52A8\u9009\u62E9\uFF0C\u6309\u603B\u7ED3\u6062\u590D\uFF1B\u201C\u8BA8\u8BBA\u8BB0\u5F55\u201D\u9875\u7684\u72EC\u7ACB\u9009\u62E9\u4F1A\u4FDD\u7559\u3002</p>
</div></section>`}function Th(e){if(e.content!==void 0)return{...e,type:"prompt"};let t=e.type==="builtin_group"?["world_before","persona","character","personality","scenario","world_after","examples"].map(n=>"{{summary."+n+"}}").join(`

